MIN_DESC = 350


def _esc(s: str) -> str:
    return s.replace("\\", "\\\\").replace('"', '\\"')


def _pad(text: str, min_len: int = MIN_DESC) -> str:
    if len(text) >= min_len:
        return text
    suffix = (
        " Contact the program directly to confirm current hours, eligibility, "
        "and intake requirements before visiting in person."
    )
    out = text
    while len(out) < min_len:
        out += suffix
    return out


def _slug(county: str) -> str:
    return county.lower().replace(".", "").replace(" ", "-")


