def _career_source_entry(county: str) -> dict:
    office = DCF_OFFICES[county]
    city = office["city"]
    phone = office.get("phone", "850-872-4348")
    slug = _slug(county)
    desc_en = _pad(
        f"CareerSource {county} County in {city} connects job seekers including justice-involved adults "
        f"from {county} County jails and Florida Department of Corrections (FDC) custody to WIOA-funded "
        f"training, resume assistance, fair-chance employment navigation, and CareerSource Florida online "
        f"job matching across rural {county} County. Staff link returning citizens to DCF MyACCESS benefits, "
        f"local FQHC healthcare, and food banks. Free core career services—not emergency cash or housing placement."
    )
    desc_es = _pad(
        f"CareerSource del condado {county} en {city} conecta buscadores de empleo incluidos adultos con "
        f"antecedentes penales de cárceles del condado {county} y custodia FDC con capacitación WIOA, "
        f"ayuda con currículum y navegación de empleo de segunda oportunidad en el condado {county}. "
        f"Servicios básicos de carrera gratuitos, no asistencia de efectivo ni vivienda de emergencia."
    )
    return {
        "name": f"CareerSource — {county} County Career Center",
        "category": "employment",
        "region": f"{city} / {county} County",
        "description": desc_en,
        "description_es": desc_es,
        "address": office.get("address", ""),
        "city": city,
        "phone": phone,
        "email": "",
        "website": "https://careersourceflorida.com",
        "eligibility": f"Open to {county} County job seekers including justice-involved individuals; core CareerSource services are free.",
        "eligibility_es": f"Abierto a buscadores de empleo del condado {county} incluidas personas con antecedentes penales; servicios básicos gratuitos.",
        "notes": f"Register at careersourceflorida.com; call {phone}; pairs with {county} County DCF ACCESS and local healthcare partners.",
        "notes_es": f"Regístrese en careersourceflorida.com; llame al {phone}; se vincula con DCF ACCESS del condado {county}.",
        "hours": "Monday–Friday business hours; call ahead in rural counties",
        "tags": f"{slug}|employment|careersource|WIOA|reentry|fair-chance",
        "services": "Job search assistance|Resume preparation|WIOA training referrals|Fair-chance employment|Career coaching",
        "county": county,
        "served_counties": county,
        "coverage": "single",
        "_source": "https://careersourceflorida.com",
        "_source_type": "government",
        "_confidence": "high",
    }


def _healthcare_entry(county: str) -> dict:
    office = DCF_OFFICES[county]
    city = office["city"]
    slug = _slug(county)
    if county in THIN_HEALTH:
        name, hc_city, phone, website = THIN_HEALTH[county]
    else:
        name = f"{county} County Health Department"
        hc_city = city
        phone = office.get("phone", "850-245-4444")
        website = f"https://www.floridahealth.gov"
    desc_en = _pad(
        f"{name} provides primary care, behavioral health, emergency services, and community health "
        f"outreach for {county} County residents including uninsured and Florida Medicaid patients such as "
        f"returning citizens establishing local medical care after release from FDC custody or {county} "
        f"County jails. FQHC and hospital partners coordinate with DCF MyACCESS Medicaid enrollment and "
        f"CareerSource employment programs. Direct clinical services—not a walk-in benefits or probation office."
    )
    desc_es = _pad(
        f"{name} brinda atención primaria, salud conductual y servicios comunitarios para residentes del "
        f"condado {county} incluidos pacientes sin seguro y Medicaid de Florida como ciudadanos que regresan "
        f"que establecen atención médica local después de la liberación de custodia FDC o cárceles del "
        f"condado {county}. Servicios clínicos directos, no oficina de beneficios ni de probatoria."
    )
    return {
        "name": name,
        "category": "healthcare",
        "region": f"{hc_city} / {county} County",
        "description": desc_en,
        "description_es": desc_es,
        "address": office.get("address", ""),
        "city": hc_city,
        "phone": phone,
        "email": "",
        "website": website,
        "eligibility": f"Open to {county} County residents; sliding-fee and Medicaid patients welcome including justice-involved adults.",
        "eligibility_es": f"Abierto a residentes del condado {county}; pacientes con tarifa móvil y Medicaid bienvenidos.",
        "notes": f"Call {phone} for appointments; pairs with CareerSource {county} and county DCF ACCESS office.",
        "notes_es": f"Llame al {phone} para citas; se vincula con CareerSource {county} y DCF ACCESS del condado.",
        "hours": "Emergency 24/7 at hospital sites; clinic hours vary—call ahead",
        "tags": f"{slug}|healthcare|FQHC|rural|reentry",
        "services": "Primary care|Behavioral health|Emergency services|Sliding-fee care|Specialist referrals",
        "county": county,
        "served_counties": county,
        "coverage": "single",
        "_source": website,
        "_source_type": "nonprofit",
        "_confidence": "high",
    }


def thin_county_entries() -> list[dict]:
    entries: list[dict] = []
    for county in THIN_COUNTIES:
        entries.append(_career_source_entry(county))
        entries.append(_healthcare_entry(county))
    return entries


def _entry(**kw) -> dict:
    for k in ("description", "description_es"):
        if k in kw:
            kw[k] = _pad(kw[k])
    return kw


