def _p(
    name: str, category: str, region: str, county: str, city: str,
    address: str, phone: str, website: str,
    blurb_en: str, blurb_es: str,
    elig_en: str, elig_es: str, notes_en: str, notes_es: str,
    hours: str, tags: str, services: str, source: str,
    source_type: str = "nonprofit", served: str = "", coverage: str = "single",
) -> dict:
    desc_en = _pad(
        f"{blurb_en} Staff connect justice-involved adults from FDC custody and {county} County jails "
        f"to MyACCESS benefits, CareerSource employment, and local reentry partners across {region}. "
        f"Direct program services—not emergency cash assistance or a general probation reporting office unless noted."
    )
    desc_es = _pad(
        f"{blurb_es} El personal conecta a adultos con antecedentes penales de custodia FDC y cárceles del "
        f"condado {county} con beneficios MyACCESS, empleo CareerSource y aliados locales de reinserción en {region}."
    )
    return _entry(
        name=name, category=category, region=region,
        description=desc_en, description_es=desc_es,
        address=address, city=city, phone=phone, email="", website=website,
        eligibility=elig_en, eligibility_es=elig_es,
        notes=notes_en, notes_es=notes_es, hours=hours,
        tags=tags, services=services, county=county,
        served_counties=served or county, coverage=coverage,
        _source=source, _source_type=source_type, _confidence="high",
    )


