def render_module_add(entry: dict) -> str:
    lines = ["    add("]
    for key in FIELD_ORDER:
        val = _esc(str(entry.get(key, "")))
        lines.append(f'            {key}="{val}",')
    lines.append("        )")
    return "\n".join(lines)


def render_build_add(entry: dict) -> str:
    lines = ["add("]
    for key in FIELD_ORDER:
        val = _esc(str(entry.get(key, "")))
        lines.append(f'        {key}="{val}",')
    lines.append("    )")
    return "\n".join(lines)


def write_module(path: Path, func_name: str, doc: str, entries: list[dict], comment: str = "") -> None:
    body = [f'"""{doc}"""', "", "", f"def {func_name}(add):"]
    if comment:
        body.append(f"    {comment}")
    for e in entries:
        body.append(render_module_add(e))
        body.append("")
    path.write_text("\n".join(body).rstrip() + "\n", encoding="utf-8")


def write_build_script() -> None:
    parts = [
        '#!/usr/bin/env python3',
        '"""Generate florida-resources.csv and florida-research-log.csv.',
        '',
        'RESOURCES_UUID_PREFIX comment de000001',
        '"""',
        'import csv',
        'from collections import Counter',
        'from pathlib import Path',
        '',
        'ROOT = Path(__file__).resolve().parents[1]',
        'RESOURCES_PATH = ROOT / "data" / "florida-resources.csv"',
        'LOG_PATH = ROOT / "data" / "florida-research-log.csv"',
        'DATE = "2026-07-06"',
        '',
        'COLUMNS = [',
        '    "id", "name", "category", "region", "description", "description_es",',
        '    "address", "city", "phone", "email", "website", "eligibility", "eligibility_es",',
        '    "notes", "notes_es", "hours", "tags", "services", "county", "served_counties", "coverage",',
        ']',
        'LOG_COLUMNS = ["source_url", "source_type", "date_accessed", "confidence", "notes", "id_reference"]',
        '',
        'ENTRIES = []',
        '',
        '',
        'def add(**kw):',
        '    ENTRIES.append(kw)',
        '',
        '',
        '# --- Phase 1: Statewide backbone ---',
    ]
    for e in PHASE1:
        parts.append(render_build_add(e))
        parts.append("")
    parts.append("# --- Phase 2: Metro depth ---")
    for e in PHASE2:
        parts.append(render_build_add(e))
        parts.append("")
    parts.extend([
        "# --- County benefits + expansion modules ---",
        "from county_benefits_registry import register_county_benefits_florida",
        "",
        "_existing_fa = {",
        '    e["county"]',
        "    for e in ENTRIES",
        '    if e["category"] == "financial-assistance" and e.get("county")',
        "}",
        "register_county_benefits_florida(add, _existing_fa)",
        "",
        "from florida_phase4_expansion import register_phase4",
        "register_phase4(add)",
        "",
        "from florida_category_fill import register_category_fill",
        "register_category_fill(add)",
        "",
        "from florida_thin_counties import register_thin_counties",
        "register_thin_counties(add)",
        "",
        "from florida_gap_fill import register_gap_fill",
        "register_gap_fill(add)",
        "",
        "",
        "def _dedupe_entries(entries: list[dict]) -> list[dict]:",
        '    """Keep one row per (name, county); prefer wider served_counties and fuller address."""',
        "    best: dict[tuple[str, str], dict] = {}",
        "    order: list[tuple[str, str]] = []",
        "    for entry in entries:",
        '        key = (entry["name"].strip().lower(), (entry.get("county") or "").strip().lower())',
        "        if key not in best:",
        "            best[key] = entry",
        "            order.append(key)",
        "            continue",
        "        cur = best[key]",
        '        cur_n = len([c for c in (cur.get("served_counties") or "").split("|") if c.strip()])',
        '        new_n = len([c for c in (entry.get("served_counties") or "").split("|") if c.strip()])',
        '        cur_addr = len(cur.get("address") or "")',
        '        new_addr = len(entry.get("address") or "")',
        "        if new_n > cur_n or (new_n == cur_n and new_addr > cur_addr):",
        "            best[key] = entry",
        "    return [best[k] for k in order]",
        "",
        "",
        "ENTRIES = _dedupe_entries(ENTRIES)",
        "",
        "for entry in ENTRIES:",
        '    if entry.get("coverage") == "single" and not entry.get("served_counties") and entry.get("county"):',
        '        entry["served_counties"] = entry["county"]',
        "",
        "log_rows = []",
        "for i, e in enumerate(ENTRIES, start=1):",
        '    e["id"] = str(i)',
        "    log_rows.append({",
        '        "source_url": e.pop("_source"),',
        '        "source_type": e.pop("_source_type"),',
        '        "date_accessed": DATE,',
        '        "confidence": e.pop("_confidence"),',
        '        "notes": f"Resource id {i}: {e[\'name\']}",',
        '        "id_reference": str(i),',
        "    })",
        "",
        'with RESOURCES_PATH.open("w", newline="", encoding="utf-8") as f:',
        "    w = csv.DictWriter(f, fieldnames=COLUMNS, quoting=csv.QUOTE_MINIMAL)",
        "    w.writeheader()",
        "    for e in ENTRIES:",
        "        row = {c: e.get(c, \"\") for c in COLUMNS}",
        "        w.writerow(row)",
        "",
        'with LOG_PATH.open("w", newline="", encoding="utf-8") as f:',
        "    w = csv.DictWriter(f, fieldnames=LOG_COLUMNS, quoting=csv.QUOTE_MINIMAL)",
        "    w.writeheader()",
        "    w.writerows(log_rows)",
        "",
        'cats = Counter(e["category"] for e in ENTRIES)',
        'low = [e for e in log_rows if e["confidence"] == "medium"]',
        'print(f"Total rows: {len(ENTRIES)}")',
        'print("Category counts:")',
        "for k, v in sorted(cats.items()):",
        '    print(f"  {k}: {v}")',
        'print(f"Low confidence: {len(low)}")',
    ])
    (SCRIPTS / "build-florida-resources.py").write_text("\n".join(parts) + "\n", encoding="utf-8")


def main() -> None:
    phase4 = phase4_entries()
    cat_fill = category_fill_entries()
    thin = thin_county_entries()
    gap = gap_fill_entries()

    write_build_script()
    write_module(
        SCRIPTS / "florida_phase4_expansion.py",
        "register_phase4",
        "Phase 4 program-level expansion entries for Florida reentry resources.",
        phase4,
    )
    write_module(
        SCRIPTS / "florida_category_fill.py",
        "register_category_fill",
        "Category minimum fill for Florida reentry resources.",
        cat_fill,
    )
    write_module(
        SCRIPTS / "florida_thin_counties.py",
        "register_thin_counties",
        "Direct-service pins for Florida counties that need local depth beyond DCF rows.",
        thin,
        '"""Two or more program-level rows per thin rural county."""',
    )
    write_module(
        SCRIPTS / "florida_gap_fill.py",
        "register_gap_fill",
        "Final category-minimum gap fill for Florida reentry resources.",
        gap,
    )

    print("Generated Florida modules:")
    print(f"  Phase 1: {len(PHASE1)} rows")
    print(f"  Phase 2: {len(PHASE2)} rows")
    print(f"  Phase 4: {len(phase4)} rows")
    print(f"  Category fill: {len(cat_fill)} rows")
    print(f"  Thin counties: {len(thin)} rows ({len(THIN_COUNTIES)} counties)")
    print(f"  Gap fill: {len(gap)} rows")


if __name__ == "__main__":
    main()
